<template><div class="page"><div class="head"><div><span>消息中心</span><h1>家庭用药提醒</h1><p>购药申请、下单、物流、收货和资金变化都汇总在这里。</p></div><el-button @click="load">刷新</el-button></div><div class="list"><el-card v-for="n in list" :key="n.notificationId" shadow="hover" :class="['notice',{unread:n.readStatus===0}]" @click="read(n)"><div><el-badge is-dot :hidden="n.readStatus===1"><strong>{{n.title}}</strong></el-badge><time>{{n.createTime}}</time></div><p>{{n.content}}</p><footer><el-tag size="small">{{n.bizType||'系统消息'}}</el-tag><span v-if="n.emailStatus==='SENT'">邮件已发送</span><span v-else-if="n.emailStatus==='FAILED'" class="fail">邮件发送失败，站内消息不受影响</span><span v-else-if="n.emailStatus==='DISABLED'">邮件待配置，站内消息已送达</span></footer></el-card><el-empty v-if="!list.length" description="暂无消息"/></div></div></template>
<script setup>import{ref,onMounted}from'vue';import{getNotifications,markNotificationRead}from'../api/family';const list=ref([]);const load=async()=>{const r=await getNotifications();list.value=r.data||[]};const read=async n=>{if(n.readStatus===0){await markNotificationRead(n.notificationId);n.readStatus=1}};onMounted(load)</script>
<style scoped>.page{max-width:950px;margin:auto}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:16px}.head span{color:#388165;font-weight:700}.head h1{margin:5px 0}.head p{margin:0;color:#758179}.list{display:grid;gap:12px}.notice{cursor:pointer;border-radius:14px}.notice.unread{border-left:5px solid #48a16b}.notice>div,.notice footer{display:flex;align-items:center;justify-content:space-between;gap:10px}.notice time,.notice footer{font-size:13px;color:#89938c}.notice p{color:#56635a;line-height:1.6}.fail{color:#d14b4b}@media(max-width:600px){.head,.notice>div,.notice footer{align-items:flex-start;flex-direction:column}}</style>
